      expect(
        hepMessageStartFrame(turnId: 1, role: 'assistant'),
        '{"type":"message_start","turn_id":1,"role":"assistant"}',
      );
    });

    test('message_delta carries the text delta', () {
      expect(
        hepMessageDeltaFrame(turnId: 1, delta: 'hel"lo\n'),
