        message: testAssistant(content: [TextContent(text: 'ok')]),
      ),
    );
    stream.end();
    return stream;
  }

  List<Tool> toolsOf(int index) => contexts[index].tools ?? const <Tool>[];

  Set<String> toolNames(int index) =>
      toolsOf(index).map((tool) => tool.name).toSet();
}

