}

private func icloudExcludeFromBackup(path: String, result: @escaping FlutterResult) {
 let fm = FileManager.default
 var target = URL(fileURLWithPath: path, isDirectory: true)
 guard fm.fileExists(atPath: target.path) else {
   result(FlutterError(code: "not_found", message: "no file at \(path)", details: nil))
   return
 }
 var toMark: [URL] = [target]
 if let enumerator = fm.enumerator(at: target, includingPropertiesForKeys: nil) {
   toMark.append(contentsOf: enumerator.allObjects.compactMap { $0 as? URL })
 }
 do {
   for url in toMark { try icloudSetExcludedFromBackup(url) }
 } catch {
   result(FlutterError(code: "exclude_failed", message: error.localizedDescription, details: nil))
   return
 }
 result(toMark.count)
}
``

