/// Test seam: replaces the channel call (unit tests record the request).
@visibleForTesting
Future<void> Function(String path)? excludeFromBackupOverride;

/// Marks the file or directory at [path] as excluded from cloud backups.
Future<void> excludePathFromBackup(String path) async {
