Simplest robust Swift: 

```swift
private func icloudSetExcludedFromBackup(_ url: URL) throws {
 var mutableUrl = url
 var values = URLResourceValues()
 values.isExcludedFromBackup = true
 try mutableUrl.setResourceValues(values)
}

private func icloudExcludeFromBackup(path: String, result: @escaping FlutterResult) {
 let fm = FileManager.default
 var target = URL(fileURLWithPath: path, isDirectory: true)
 guard fm.fileExists(atPath: target.path) else {
   result(FlutterError(code: "not_found", message: "no file at \(path)", details: nil))
   return
 }
 var toMark: [URL] = [target]
 if let enumerator = fm.enumerator(at: target, includingPropertiesForKeys: nil) {
   toMark.append(contentsOf: enumerator.allObjects.compactMap { $0 as? URL })
 }
 do {
   for url in toMark { try icloudSetExcludedFromBackup(url) }
 } catch {
   result(FlutterError(code: "exclude_failed", message: error.localizedDescription, details: nil))
   return
 }
 result(toMark.count)
}
``

Hmm, do I want to walk descendants? The review says "set the NSURLIsExcludedFromBackupKey URL resource key on the sandbox `.dap` subtree". Apple's documentation for `isExcludedFromBackup` is actually explicit: "The value is true if the resource is excluded from backups... For directories, the flag excludes the directory AND its contents"? Let me just check the actual Apple doc text: URLResourceKey.isExcludedFromBackupKey: "If this value is true, the system does not back up this file or directory. ... exclude a directory: the entire contents are excluded"? 

From Apple docs on `isExcludedFromBackup` (Foundation): "Setting this property to true prevents the file or directory from being backed up... If you set it on a directory, the system does not back up the directory or any of its contents." I believe this is accurate for the modern backupd — BUT there are well-known reports (and Apple QA1719's structure) that files ADED LATER to an excluded directory ARE still excluded (backupd re-evaluates at backup time by walking; the directory flag prunes the walk). The main gotcha is with EXCLUDING files inside INCLUDED dirs. So setting on `.dap` dir alone is sufficient; walking descendants adds robustness for the upgrade path where... no wait — if the directory flag prunes the whole walk, descendants don't matter at all. The walker is belt-and-braces; harmless and cheap (dir is tiny). I'll include it — it directly matches the reviewer's "on the sandbox .dap subtree" wording.

