    result(healthEmptySummary())
    return
  }
  let span = min(max(days, 1), 31)
  let calendar = Calendar.current
  let today = calendar.startOfDay(for: Date())
  guard let start = calendar.date(byAdding: .day, value: -(span - 1), to: today) else {
    result(healthEmptySummary())
    return
  }
  let end = Date()
  let group = DispatchGroup()
  var steps: [[String: Any]] = []
  var resting: [[String: Any]] = []
  var sleep: [[String: Any]] = []

  group.enter()
  healthQuantitySeries(
    type: HKQuantityType(.stepCount),
    unit: .count(),
    options: .cumulativeSum,
    start: start,
    end: end,
  ) { entries in
    steps = entries
    group.leave()
  }

  group.enter()
  healthQuantitySeries(
    type: HKQuantityType(.restingHeartRate),
    unit: HKUnit.count().unitDivided(by: .minute()),
    options: .discreteAverage,
    start: start,
    end: end,
  ) { entries in
    resting = entries
    group.leave()
  }

  group.enter()
  healthSleepSeries(start: start) { entries in
    sleep = entries
    group.leave()
  }

  group.notify(queue: .main) {
    result([
      "steps": steps,
      "restingHeartRate": resting,
      "sleepHours": sleep,
    ])
  }
}

