    case "summary":
      let args = call.arguments as? [String: Any] ?? [:]
      let days = (args["days"] as? NSNumber)?.intValue ?? 7
      healthSummary(days: days, result: result)
    default:
      result(FlutterMethodNotImplemented)
    }
  }
