        // settles last — the wire contract pi/claude-code consumers parse.
        expect(parsed.first['type'], 'session');
        expect(parsed.first['id'], isNotNull);
        expect(parsed.first['cwd'], '/work');
        expect(parsed.last['type'], 'agent_settled');
        expect(
