          containsAllInOrder([
            'session',
            'agent_start',
            'tool_execution_start',
            'tool_execution_end',
            'agent_settled',
          ]),
        );
        // The tool round rides the stream with its call identity.
        final toolStart = parsed.firstWhere(
          (e) => e['type'] == 'tool_execution_start',
        );
        expect(toolStart['toolName'], 'read');
        expect(toolStart['toolCallId'], 'c1');
      },
    );
  });

