          containsAllInOrder([
            'hep_header',
            'agent_start',
            'tool_start',
            'turn_done',
          ]),
        );
        final last = parsed.last;
        expect(last['type'], 'turn_done');
        expect(last['message'], 'done reading');
      },
    );
  });

