        expect(parsed.first['cwd'], '/work');
        expect(parsed.last['type'], 'agent_settled');
        expect(
          parsed.map((e) => e['type']),
          containsAllInOrder([
            'session',
            'agent_start',
            'tool_execution_start',
            'tool_execution_end',
            'agent_settled',
          ]),
        );
