{"command":"cd /home/runner/work/flutter_agent_harness/flutter_agent_harness && ls -la /tmp/lcov.new.info && python3 - <<'EOF'
def load(path):
    files={}
    cur=None
    for line in open(path,encoding='utf-8',errors='replace'):
        line=line.strip()
        if line.startswith('SF:'):
            cur=line[3:]; files.setdefault(cur,{})
        elif line.startswith('DA:') and cur is not None:
            try: ln,hits=line[3:].split(',')[:2]
            except ValueError: continue
            h=int(hits); files[cur][ln]=max(files[cur].get(ln,0),h)
    return files

base_files={}
for s in ('shard0','shard1','shard2'):
    for f,d in load(f'/tmp/covshards/{s}/lcov.info').items():
        base_files.setdefault(f,{}).update({k:max(base_files[f].get(k,0),v) for k,v in d.items()} if f in base_files else d)

new=load('/tmp/lcov.new.info')

def cli_stats(files):
    tot=hit=0
    for f,d in files.items():
        if '/lib/src/cli/' not in f: continue
        for v in d.values():
            tot+=1; hit+= 1 if v>0 else 0
    return hit,tot

bh,bt=cli_stats(base_files)
print(f'base (failed CI run merged): {bh}/{bt} = {100*bh/bt:.4f}%')

# union merge with the new file's coverage
for f,d in new.items():
    if f not in base_files:
        base_files[f]=dict(d)
    else:
        for k,v in d.items():
            base_files[f][k]=max(base_files[f].get(k,0),v)
ah,at=cli_stats(base_files)
print(f'union with new integration file: {ah}/{at} = {100*ah/at:.4f}%  (baseline 18.42)')
print(f'new hits added: {ah-bh}')

# which cli files gained
for f,d in new.items():
    if '/lib/src/cli/' not in f: continue
    b=base_files[f]
    gained=sum(1 for k,v in d.items() if v>0 and b.get(k,0)==0)
    if gained: print(f'  +{gained:4} {f.split("flutter_agent_harness/")[-1]}')
EOF","timeout":120}

